export const grammarCategories=[
 {id:'v2',title:'Порядок слов: V2 и инверсия',tip:'В главном предложении спрягаемый глагол стоит на втором месте. Если вперёд выносится обстоятельство, дополнение или придаточное, подлежащее уходит за глагол: «I morgen kommer vi tidligt»; «Fordi det regnede, blev vi hjemme».'},
 {id:'bisaet',title:'Придаточные: порядок слов (ikke, aldrig, ofte…)',tip:'В придаточном подлежащее стоит сразу после союза, а наречия ikke, aldrig, ofte, altid, også — перед глаголом: «Jeg ved, at han ikke kommer». В главном предложении они стоят после глагола: «Han kommer ikke».'},
 {id:'passive',title:'Пассив (-s, blive + причастие)',tip:'Пассив образуется двумя способами: s-формой («Brevet sendes i dag») и blive + причастие («Brevet bliver sendt i dag»). После модальных глаголов нужен инфинитив: «Bilen skal repareres» или «Bilen skal blive repareret»; в прошедшем времени обычно «blev»: «Bilen blev repareret».'},
 {id:'tenses',title:'Времена: præteritum, perfektum, pluskvamperfektum',tip:'Præteritum — завершённое действие в прошлом, обычно с указанием времени: «I går læste jeg bogen». Perfektum (har/er + причастие) связывает прошлое с настоящим: «Jeg har læst bogen». Pluskvamperfektum (havde/var + причастие) — действие раньше другого прошлого: «Da jeg kom, var han gået».'},
 {id:'relative',title:'Относительные и вопросительные слова (som, der, hvad, hvilken)',tip:'Som подходит и для подлежащего, и для дополнения: «Manden, som bor her» и «Manden, som jeg kender»; der — только для подлежащего: «Manden, der bor her». Hvad значит «то, что» («Jeg forstår, hvad du mener»), а hvilken/hvilket/hvilke ставится перед существительным: «Hvilken bog vil du læse?».'},
 {id:'connect',title:'Союзы и связки (fordi, selvom, medmindre, derfor…)',tip:'Fordi вводит причину, selvom — уступку («Selvom det regnede, gik vi en tur»), medmindre — «если только не». После наречий derfor, alligevel, desværre в начале предложения глагол идёт сразу за ними: «Det regnede. Derfor blev vi hjemme». Для однократного прошлого события используется da, для повторяющегося и будущего — når.'},
 {id:'prep',title:'Предлоги и устойчивые сочетания',tip:'Многие глаголы, прилагательные и существительные требуют определённого предлога, и его нужно учить вместе со словом: «at tænke på», «at være stolt af», «at have brug for», «at deltage i». Предлог часто не совпадает с русским.'},
 {id:'agree',title:'Согласование: род, число, определённость',tip:'Прилагательное согласуется с существительным: en stor bil, et stort hus, store huse. После определённого артикля прилагательное имеет форму на -e, а существительное стоит без суффикса: den store bil, det store hus, de store huse. Без прилагательного определённость показывает суффикс: bilen, huset, husene.'},
 {id:'reflex',title:'Возвратные и притяжательные (sin/hans/hendes, sig)',tip:'Sig, sin, sit, sine указывают на подлежащее своего же предложения: «Peter vasker sin bil» (свою), но «Peter vasker hans bil» — машину другого мужчины. Sig стоит при возвратных глаголах 3-го лица («Hun glæder sig»), а при vi, jeg, du нужны os, mig, dig.'},
 {id:'modal',title:'Модальные глаголы и инфинитив (at / без at)',tip:'После модальных (kunne, skulle, ville, måtte, burde, bør) стоит инфинитив без at: «Du skal komme». После большинства других глаголов и прилагательных инфинитив идёт с at: «Det er svært at forklare»; «Jeg plejer at stå tidligt op».'},
 {id:'compare',title:'Степени сравнения и количество (mere, flere, færre, mest)',tip:'Степени сравнения: høj – højere – højest; mange – flere – flest; lidt – mindre – mindst; god – bedre – bedst. Flere и færre — с исчисляемыми («flere bøger»), mere и mindre — с неисчисляемыми («mere tid»). Для сравнения: «højere end», «lige så høj som», «jo mere, desto bedre».'},
 {id:'cond',title:'Условные и желательные конструкции (hvis, ville, kunne, havde)',tip:'Реальное условие: «Hvis det regner, bliver jeg hjemme». Нереальное в настоящем: hvis + præteritum и ville + инфинитив: «Hvis jeg havde tid, ville jeg komme». Нереальное в прошлом: hvis + havde + причастие и ville have + причастие. Желание: «Gid jeg havde mere tid».'}
];

export const grammarSetsB=[
{id:'gram-7',title:'Grammatik B2 – sæt 7',level:'B2',minutes:15,items:[
 {id:'g7-01',cat:'prep',type:'gap',stem:'Han har desværre ikke råd ___ at købe en ny bil.',options:['for','med','til','af'],answer:2,why:'Устойчивое сочетание «have råd til at …» (позволить себе). Предлоги for, med и af с существительным råd так не употребляются.'},
 {id:'g7-02',cat:'modal',type:'fix',sentence:'Mine forældre vil gerne flytter til Aarhus, når de går på pension.',errorIndex:4,fixes:['flytte'],why:'После модального глагола vil стоит инфинитив без окончания -r: «vil gerne flytte». Форма flytter — настоящее время, после модального она невозможна.'},
 {id:'g7-03',cat:'v2',type:'order',tokens:['besluttet','sige','jeg','derfor','har','at','op.'],answers:['Derfor har jeg besluttet at sige op.','Jeg har derfor besluttet at sige op.'],why:'Если вперёд вынесено «derfor», спрягаемый глагол остаётся на втором месте, а подлежащее идёт за ним: «Derfor har jeg …». Возможен и прямой порядок: «Jeg har derfor …».'},
 {id:'g7-04',cat:'agree',type:'gap',stem:'Børnene i klassen er så ___, at læreren næsten aldrig behøver at hjælpe dem.',options:['dygtige','dygtig','dygtigt','dygtigere'],answer:0,why:'Сказуемое согласуется с подлежащим «børnene» (мн. число), поэтому форма на -e: dygtige. Dygtig и dygtigt — формы единственного числа, dygtigere — сравнительная степень, после «så» она невозможна.'},
 {id:'g7-05',cat:'passive',type:'transform',prompt:'Man renoverer rådhuset i løbet af sommeren.',instruction:'Перепиши в пассиве без исполнителя, время то же (презенс).',answers:['Rådhuset renoveres i løbet af sommeren.','Rådhuset bliver renoveret i løbet af sommeren.','I løbet af sommeren renoveres rådhuset.','I løbet af sommeren bliver rådhuset renoveret.'],why:'Пассив без исполнителя образуется s-формой (renoveres) или blive + причастие (bliver renoveret); «man» исчезает. Если обстоятельство стоит в начале, подлежащее идёт после глагола.'},
 {id:'g7-06',cat:'connect',type:'cloze',segments:['Sofie har lige fået et nyt job i en lille virksomhed i Silkeborg. ',{gap:1,options:['Fordi','Selvom','Hvis','Medmindre'],answer:1},' hun er glad for arbejdet, savner hun sine gamle kolleger. Hun står op klokken seks, ',{gap:2,options:['selvom','så','derfor','fordi'],answer:3},' hun har en lang vej til arbejde. Hun tager toget, ',{gap:3,options:['fordi','selvom','medmindre','derfor'],answer:0},' det er billigere end at køre i bil. ',{gap:4,options:['Fordi','Selvom','Desværre','Medmindre'],answer:2},' er toget ofte forsinket, så hun kommer nogle gange for sent. Hun er træt om aftenen, ',{gap:5,options:['fordi','derfor','selvom','men'],answer:3},' hun har alligevel energi til at gå en tur med hunden.'],why:'Selvom вводит уступку, fordi — причину. После наречия «Desværre» в начале предложения глагол идёт сразу за ним («er toget»). Противопоставление двух главных частей выражает men; derfor, fordi и selvom дали бы неверный порядок слов или смысл.'},
 {id:'g7-07',cat:'relative',type:'fix',sentence:'Det er den bog, der jeg har ledt efter i flere uger.',errorIndex:4,fixes:['som'],why:'Der возможно только тогда, когда оно само подлежащее придаточного. Здесь подлежащее — «jeg», а относительное слово — дополнение, поэтому нужно som: «den bog, som jeg har ledt efter».'},
 {id:'g7-08',cat:'bisaet',type:'order',tokens:['skulle','vi','til','læreren','altid','at','tiden.','aflevere','opgaven','sagde,'],answers:['Læreren sagde, at vi altid skulle aflevere opgaven til tiden.'],why:'В придаточном после at наречие altid стоит перед спрягаемым глаголом: «at vi altid skulle aflevere». В главном предложении оно стояло бы после глагола.'},
 {id:'g7-09',cat:'tenses',type:'transform',prompt:'Da vi kom hjem, ryddede Mads op i køkkenet.',instruction:'Покажи, что Mads закончил уборку до нашего прихода (pluskvamperfektum). Остальное не меняй.',answers:['Da vi kom hjem, havde Mads ryddet op i køkkenet.','Mads havde ryddet op i køkkenet, da vi kom hjem.'],why:'Действие, завершившееся раньше другого прошлого действия, ставится в pluskvamperfektum: havde + причастие (havde ryddet op).'},
 {id:'g7-10',cat:'reflex',type:'gap',stem:'Min bedstemor har altid interesseret ___ for politik.',options:['hende','sig','sin','sit'],answer:1,why:'«Interessere sig for» — возвратный глагол, нужно sig. Hende — не возвратное местоимение, а sin и sit — притяжательные и требуют существительного.'}
]},
{id:'gram-8',title:'Grammatik B2 – sæt 8',level:'B2',minutes:15,items:[
 {id:'g8-01',cat:'compare',type:'gap',stem:'Der kom ___ gæster til festen, end vi havde regnet med.',options:['mere','flere','mest','flest'],answer:1,why:'Gæster — исчисляемое существительное во мн. числе; сравнительная степень от «mange» — flere. Mere употребляется с неисчисляемыми («mere tid»), а mest и flest — превосходные степени, с «end» они не сочетаются.'},
 {id:'g8-02',cat:'agree',type:'fix',sentence:'Jeg kan rigtig godt lide den gamle hus på hjørnet.',errorIndex:5,fixes:['det'],why:'Hus — существительное среднего рода (et hus), поэтому определённый артикль det, а не den: «det gamle hus». Форма прилагательного gamle правильная.'},
 {id:'g8-03',cat:'bisaet',type:'order',tokens:['tror,','jeg','ikke','han','at','desværre','kommer','til','festen.'],answers:['Jeg tror, at han desværre ikke kommer til festen.','Jeg tror desværre ikke, at han kommer til festen.'],why:'В придаточном после at наречия стоят перед глаголом: сначала оценочное desværre, затем ikke — «at han desværre ikke kommer».'},
 {id:'g8-04',cat:'v2',type:'gap',stem:'Normalt står jeg tidligt op, men i går ___ først op klokken ni.',options:['jeg stod','jeg står','står jeg','stod jeg'],answer:3,why:'После вынесенного вперёд «i går» глагол остаётся на втором месте, подлежащее идёт за ним: «stod jeg». Форма stod — præteritum, как требует «i går»; «jeg stod» нарушает V2, а «står» — настоящее время.'},
 {id:'g8-05',cat:'cond',type:'transform',prompt:'Hvis det regner, bliver vi hjemme.',instruction:'Сделай условие нереальным: hvis + præteritum, в главной части ville + инфинитив.',answers:['Hvis det regnede, ville vi blive hjemme.','Vi ville blive hjemme, hvis det regnede.'],why:'Нереальное условие в настоящем: hvis + præteritum (regnede), главная часть — ville + инфинитив (ville blive). Придаточное можно поставить в начало или в конец.'},
 {id:'g8-06',cat:'prep',type:'cloze',segments:['Familien Lund bor ',{gap:1,options:['i','på','til','af'],answer:0},' Aalborg, men næste sommer skal de flyve ',{gap:2,options:['på','i','til','ved'],answer:2},' Rom. Børnene glæder sig meget ',{gap:3,options:['efter','til','for','af'],answer:1},' rejsen, og datteren er især optaget ',{gap:4,options:['i','for','på','af'],answer:3},' gamle bygninger og kunst. Faren har allerede betalt ',{gap:5,options:['til','af','for','efter'],answer:2},' billetterne, og moren har lavet en lang liste over, hvad de skal pakke. Børnene vil gerne have mange bøger med i kufferten.'],why:'Устойчивые сочетания: bo i + город, flyve til, glæde sig til, være optaget af, betale for.'},
 {id:'g8-07',cat:'tenses',type:'fix',sentence:'Vi var allerede spist, da gæsterne ankom.',errorIndex:1,fixes:['havde'],why:'Еда закончилась раньше, чем гости пришли, поэтому нужен pluskvamperfektum: havde + причастие. Var + причастие используется лишь с глаголами движения и изменения состояния, а spise к ним не относится.'},
 {id:'g8-08',cat:'relative',type:'order',tokens:['jeg','er','som','den','har','det','lærer,','fortalt','om.','dig'],answers:['Det er den lærer, som jeg har fortalt dig om.'],why:'В относительном придаточном с som предлог остаётся в конце: «som jeg har fortalt dig om». Подлежащее jeg стоит перед глаголом har.'},
 {id:'g8-09',cat:'connect',type:'transform',prompt:'Han var syg. Han gik alligevel på arbejde.',instruction:'Объедини два предложения в одно с союзом selvom, смысл не меняй.',answers:['Selvom han var syg, gik han på arbejde.','Han gik på arbejde, selvom han var syg.'],why:'Selvom вводит уступительное придаточное. Если оно стоит в начале предложения, в главной части происходит инверсия: «Selvom han var syg, gik han …». Слово alligevel больше не нужно.'},
 {id:'g8-10',cat:'passive',type:'gap',stem:'Huset ___ bygget i 1950’erne og er senere blevet renoveret to gange.',options:['blev','bliver','blive','blevet'],answer:0,why:'Пассив в прошедшем времени: blev + причастие (blev bygget). Bliver — настоящее время, blive — инфинитив, а blevet требует вспомогательного глагола har/er.'}
]},
{id:'gram-9',title:'Grammatik B2 – sæt 9',level:'B2',minutes:15,items:[
 {id:'g9-01',cat:'reflex',type:'gap',stem:'Vi sidder og hygger ___ med levende lys.',options:['sig','dem','jer','os'],answer:3,why:'Глагол «hygge sig» возвратный; при подлежащем «vi» возвратное местоимение — os: «vi hygger os». Sig относится только к 3-му лицу, dem и jer — не возвратные формы для «vi».'},
 {id:'g9-02',cat:'v2',type:'fix',sentence:'Næste år rejse vi til Norge i påsken.',errorIndex:2,fixes:['rejser'],why:'В главном предложении после вынесенного вперёд обстоятельства на втором месте должен стоять спрягаемый глагол (rejser), а не инфинитив.'},
 {id:'g9-03',cat:'bisaet',type:'order',tokens:['hun','aldrig','at','fortalte,','været','i','havde','Italien.','hun'],answers:['Hun fortalte, at hun aldrig havde været i Italien.'],why:'В придаточном aldrig стоит перед спрягаемым глаголом: «at hun aldrig havde været». В главном предложении порядок был бы другим: «hun havde aldrig været».'},
 {id:'g9-04',cat:'cond',type:'transform',prompt:'Jeg havde ikke penge nok, så jeg købte ikke cyklen.',instruction:'Опиши нереальное прошлое: начни с «Hvis jeg havde haft penge nok, …».',answers:['Hvis jeg havde haft penge nok, ville jeg have købt cyklen.','Hvis jeg havde haft penge nok, havde jeg købt cyklen.'],why:'Нереальное условие в прошлом: hvis + pluskvamperfektum (havde haft), в главной части ville have + причастие или, в разговорной речи, havde + причастие.'},
 {id:'g9-05',cat:'modal',type:'gap',stem:'Du bør ___ lægen, hvis smerterne ikke går væk.',options:['kontakte','at kontakte','kontaktet','kontakter'],answer:0,why:'После модального глагола bør стоит инфинитив без at: «bør kontakte». Kontaktet — причастие, kontakter — настоящее время, а «at kontakte» после модального не употребляется.'},
 {id:'g9-06',cat:'compare',type:'cloze',segments:['I år er der kommet ',{gap:1,options:['mere','flere','mest','flest'],answer:1},' elever på skolen end sidste år. Den nye bygning er ',{gap:2,options:['stor','størst','største','større'],answer:3},' end den gamle, så der er plads til alle. Eleverne synes, at skolegården er det ',{gap:3,options:['hyggeligste','hyggeligere','hyggelig','hyggeligt'],answer:0},' sted af alle. Nogle lærere har ',{gap:4,options:['flere','flest','mere','mest'],answer:2},' erfaring end andre, men alle er lige så dygtige ',{gap:5,options:['end','som','at','og'],answer:1},' rektoren.'],why:'Flere — с исчисляемыми («elever»), mere — с неисчисляемыми («erfaring»). Сравнение: «større end». После «af alle» нужна превосходная степень: «det hyggeligste». Равенство: «lige så dygtige som».'},
 {id:'g9-07',cat:'passive',type:'fix',sentence:'Bygningen skal bliver revet ned næste år.',errorIndex:2,fixes:['blive'],why:'После модального глагола skal нужен инфинитив: «skal blive revet ned». Форма bliver — настоящее время, после модального она невозможна.'},
 {id:'g9-08',cat:'tenses',type:'transform',prompt:'Hver sommer tager vi til Fanø, og børnene bygger sandslotte.',instruction:'Поставь все глаголы в præteritum.',answers:['Hver sommer tog vi til Fanø, og børnene byggede sandslotte.'],why:'Præteritum неправильного глагола: tager → tog; правильного: bygger → byggede. Порядок слов не меняется.'},
 {id:'g9-09',cat:'relative',type:'order',tokens:['egentlig','jeg','hvad','ikke,','slet','du','forstår','mener.'],answers:['Jeg forstår slet ikke, hvad du egentlig mener.','Hvad du egentlig mener, forstår jeg slet ikke.'],why:'В придаточном с hvad подлежащее и наречие стоят перед глаголом: «hvad du egentlig mener». Придаточное можно вынести в начало, тогда в главной части — инверсия: «forstår jeg».'},
 {id:'g9-10',cat:'connect',type:'gap',stem:'Han havde ikke sovet i to dage. ___ var han overraskende frisk.',options:['Fordi','Selvom','Alligevel','Medmindre'],answer:2,why:'Alligevel — наречие, а не союз: после него главное предложение с инверсией («var han»). Fordi, selvom и medmindre вводят придаточные, и порядок слов с ними был бы другим.'}
]},
{id:'gram-10',title:'Grammatik B2 – sæt 10',level:'B2',minutes:15,items:[
 {id:'g10-01',cat:'passive',type:'gap',stem:'Rapporten skal ___ afleveret senest fredag.',options:['bliver','blive','blev','blevet'],answer:1,why:'После модального skal нужен инфинитив: «skal blive afleveret» (пассив). Bliver и blev — личные формы, blevet требует вспомогательного глагола har/er.'},
 {id:'g10-02',cat:'reflex',type:'fix',sentence:'Vi glæder sig alle til ferien.',errorIndex:2,fixes:['os'],why:'При подлежащем «vi» возвратное местоимение — os: «vi glæder os». Sig употребляется только при подлежащем 3-го лица.'},
 {id:'g10-03',cat:'modal',type:'order',tokens:['ikke','vi','festen.','komme','desværre','til','kan'],answers:['Vi kan desværre ikke komme til festen.','Desværre kan vi ikke komme til festen.'],why:'После модального глагола kan стоит инфинитив без at: «kan komme». Наречия desværre и ikke идут после подлежащего; если desværre вынесено вперёд, подлежащее встаёт за глаголом.'},
 {id:'g10-04',cat:'v2',type:'transform',prompt:'Jeg tog toget, fordi bilen var på værksted.',instruction:'Начни с придаточного «Fordi …» и поставь главную часть в правильном порядке слов.',answers:['Fordi bilen var på værksted, tog jeg toget.'],why:'Придаточное в начале предложения занимает первую позицию, поэтому в главной части глагол стоит сразу после запятой, а подлежащее — за ним: «…, tog jeg toget».'},
 {id:'g10-05',cat:'prep',type:'gap',stem:'Vi er nødt til at tage hensyn ___ de ældre beboere.',options:['for','af','til','med'],answer:2,why:'Устойчивое сочетание «tage hensyn til» (учитывать). Другие предлоги с hensyn здесь не употребляются.'},
 {id:'g10-06',cat:'agree',type:'cloze',segments:['Vi er flyttet ind i ',{gap:1,options:['en','et','det','nogen'],answer:0},' lejlighed i centrum, og vi er meget glade for den. Lejligheden er billig, men køkkenet er ikke særlig ',{gap:2,options:['pæn','pæne','pænere','pænt'],answer:3},'. Vi har købt to nye ',{gap:3,options:['stol','stole','stolen','stolene'],answer:1},' og et ',{gap:4,options:['stor','størst','stort','store'],answer:2},' bord til spisestuen. ',{gap:5,options:['De','Den','Det','Dem'],answer:0},' nye naboer virker meget rare, så vi tror, at vi kommer til at trives her.'],why:'En lejlighed — общий род; køkkenet (et køkken) требует формы среднего рода pænt; после «to nye» существительное во мн. числе без артикля (stole); «et stort bord» — средний род; «De nye naboer» — определённое мн. число.'},
 {id:'g10-07',cat:'compare',type:'fix',sentence:'Der kom mere mennesker til festen, end vi havde håbet, så vi løb tør for mad.',errorIndex:2,fixes:['flere'],why:'Mennesker — исчисляемое существительное во мн. числе, поэтому нужна форма flere (сравнительная степень от «mange»). Mere употребляется только с неисчисляемыми: «mere mad».'},
 {id:'g10-08',cat:'bisaet',type:'order',tokens:['filmen','ved,','du','har','jeg','at','endnu.','ikke','set'],answers:['Jeg ved, at du ikke har set filmen endnu.','Jeg ved, at du endnu ikke har set filmen.'],why:'В придаточном ikke стоит перед спрягаемым глаголом: «at du ikke har set». Наречие endnu можно поставить в конец или перед ikke («endnu ikke»).'},
 {id:'g10-09',cat:'tenses',type:'transform',prompt:'Mette ringede til sin mor.',instruction:'Перепиши в perfektum и добавь слово allerede.',answers:['Mette har allerede ringet til sin mor.','Mette har ringet til sin mor allerede.'],why:'Perfektum образуется из har + причастие (har ringet). Наречие allerede стоит после har или, реже, в конце предложения.'},
 {id:'g10-10',cat:'cond',type:'gap',stem:'Hvis jeg ___ mere tid, ville jeg lære at spille klaver.',options:['har','ville have','har haft','havde'],answer:3,why:'Нереальное условие в настоящем: hvis + præteritum (havde), в главной части ville + инфинитив. Har, har haft и ville have в придаточном с hvis здесь не подходят.'}
]},
{id:'gram-11',title:'Grammatik B2 – sæt 11',level:'B2',minutes:15,items:[
 {id:'g11-01',cat:'agree',type:'gap',stem:'Har du set ___ nye bil, som Karl har købt?',options:['de','den','det','dem'],answer:1,why:'Bil — слово общего рода (en bil), поэтому перед прилагательным нужен артикль den: «den nye bil». De — для мн. числа, det — для среднего рода, dem — не артикль.'},
 {id:'g11-02',cat:'reflex',type:'fix',sentence:'Børnene skal nok klare dem selv, mens vi er væk.',errorIndex:4,fixes:['sig'],why:'Когда местоимение относится к подлежащему («børnene»), нужна возвратная форма sig: «klare sig selv». Dem означало бы других людей.'},
 {id:'g11-03',cat:'v2',type:'order',tokens:['vi','efter','fest.','holdt','stor','eksamen','en'],answers:['Efter eksamen holdt vi en stor fest.','Vi holdt en stor fest efter eksamen.'],why:'Если вперёд вынесено «efter eksamen», подлежащее уходит за глагол: «holdt vi». При прямом порядке подлежащее стоит первым: «Vi holdt …».'},
 {id:'g11-04',cat:'relative',type:'gap',stem:'___ af de to film vil du helst se i aften?',options:['Hvilket','Hvad','Hvilken','Hvem'],answer:2,why:'В вопросе с выбором из нескольких предметов употребляется hvilken/hvilket/hvilke по роду: film — общего рода (en film), значит hvilken. Hvad и hvem с «af de to film» не сочетаются.'},
 {id:'g11-05',cat:'cond',type:'transform',prompt:'Jeg ville ønske, at jeg havde mere tid.',instruction:'Выскажи то же желание короче, начав со слова Gid.',answers:['Gid jeg havde mere tid.','Gid jeg bare havde mere tid.'],why:'Желание, которое трудно исполнить, выражается конструкцией «Gid» + подлежащее + præteritum: «Gid jeg havde mere tid». Союз at не нужен.'},
 {id:'g11-06',cat:'prep',type:'cloze',segments:['Mette er vokset op ',{gap:1,options:['på','i','ved','til'],answer:0},' Fyn, men hun bor nu ',{gap:2,options:['på','til','i','fra'],answer:2},' København. Hun er ansvarlig ',{gap:3,options:['af','for','til','med'],answer:1},' kontakten til forfatterne, og hun er meget glad ',{gap:4,options:['af','til','på','for'],answer:3},' sit job. Efter arbejde mødes hun ofte ',{gap:5,options:['med','til','af','for'],answer:0},' sine veninder, og de spiser sammen på en lille restaurant tæt på banegården. I weekenden tager hun ofte på cykeltur med sin kæreste.'],why:'Устойчивые сочетания: vokse op på + остров, bo i + город, ansvarlig for, glad for, mødes med.'},
 {id:'g11-07',cat:'bisaet',type:'fix',sentence:'Hun spurgte, at jeg havde lyst til at komme med.',errorIndex:2,fixes:['om'],why:'Косвенный вопрос без вопросительного слова вводится союзом om: «spurgte, om jeg havde lyst». Союз at используется после утверждений. Порядок слов в придаточном правильный.'},
 {id:'g11-08',cat:'modal',type:'order',tokens:['at','du','døren.','ikke','må','låse','glemme'],answers:['Du må ikke glemme at låse døren.'],why:'После модального må инфинитив без at («må ikke glemme»), а после глагола glemme инфинитив идёт с at («glemme at låse»). Ikke стоит после подлежащего и модального глагола.'},
 {id:'g11-09',cat:'connect',type:'transform',prompt:'Vi tager på picnic i morgen, hvis det ikke regner.',instruction:'Замени hvis … ikke на medmindre. Смысл не меняй.',answers:['Vi tager på picnic i morgen, medmindre det regner.','Medmindre det regner, tager vi på picnic i morgen.'],why:'Medmindre значит «если только не» и заменяет hvis … ikke: «medmindre det regner». Если придаточное стоит в начале, в главной части — инверсия: «tager vi».'},
 {id:'g11-10',cat:'compare',type:'gap',stem:'Jo ___ jeg øver mig, desto bedre bliver jeg.',options:['mest','meget','flere','mere'],answer:3,why:'Конструкция «jo … desto» требует сравнительной степени: «jo mere … desto bedre». Mest — превосходная, flere употребляется с исчисляемыми существительными, meget сравнительной степени не образует.'}
]},
{id:'gram-12',title:'Grammatik B2 – sæt 12',level:'B2',minutes:15,items:[
 {id:'g12-01',cat:'modal',type:'gap',stem:'Det kan være svært ___ finde en billig lejlighed i København.',options:['at','til at','for at','så at'],answer:0,why:'После прилагательного svært инфинитив стоит с at: «svært at finde». Обороты «for at» и «til at» выражают цель или назначение и здесь не подходят.'},
 {id:'g12-02',cat:'connect',type:'fix',sentence:'Når jeg kom hjem i går, var min mor allerede gået.',errorIndex:0,fixes:['Da'],why:'Для однократного события в прошлом в придаточном времени нужен da, а når — для настоящего, будущего и повторяющихся действий: «Da jeg kom hjem i går, …».'},
 {id:'g12-03',cat:'cond',type:'order',tokens:['ville','hvis','tid,','jeg','gerne','havde','komme.','jeg'],answers:['Hvis jeg havde tid, ville jeg gerne komme.','Jeg ville gerne komme, hvis jeg havde tid.'],why:'Нереальное условие: hvis + præteritum (havde), в главной части ville + инфинитив. Если придаточное стоит первым, в главной части инверсия: «ville jeg».'},
 {id:'g12-04',cat:'prep',type:'gap',stem:'Han er blevet gift ___ en dansk kvinde.',options:['til','af','for','med'],answer:3,why:'Устойчивое сочетание «gift med» (женат на, замужем за). Предлоги til, af и for так не употребляются.'},
 {id:'g12-05',cat:'passive',type:'transform',prompt:'Politiet har fundet den stjålne cykel.',instruction:'Перепиши в пассиве (perfektum) без исполнителя.',answers:['Den stjålne cykel er blevet fundet.','Den stjålne cykel er fundet.'],why:'Пассив в perfektum: er blevet + причастие (er blevet fundet); допустима и краткая форма «er fundet». Исполнитель («politiet») опускается.'},
 {id:'g12-06',cat:'tenses',type:'cloze',segments:['Da jeg ',{gap:1,options:['var','har været','havde været','er'],answer:0},' barn, boede vi på en gård i Jylland. Hver sommer ',{gap:2,options:['kommer','komme','kom','kommet'],answer:2},' mine kusiner på besøg, og vi legede sammen på marken. Sidste år ',{gap:3,options:['besøger','besøgte','besøge','besøgt'],answer:1},' jeg gården igen, men den ',{gap:4,options:['er','havde','blev','var'],answer:3},' blevet solgt to år tidligere. Jeg ',{gap:5,options:['har','er','havde','var'],answer:2},' aldrig tænkt på, at det kunne ske, før jeg stod der.'],why:'Рассказ о прошлом ведётся в præteritum: var, kom, besøgte. Более раннее действие требует pluskvamperfektum: «var blevet solgt», «havde aldrig tænkt».'},
 {id:'g12-07',cat:'agree',type:'fix',sentence:'De store huset ligger tæt på havnen.',errorIndex:2,fixes:['huse'],why:'После «De store» существительное стоит во мн. числе без определённого суффикса: «de store huse». Huset — форма единственного числа.'},
 {id:'g12-08',cat:'reflex',type:'order',tokens:['Peter','har','klædt','sig','på','og','fundet','sin','hue.'],answers:['Peter har klædt sig på og fundet sin hue.','Peter har fundet sin hue og klædt sig på.'],why:'Sig стоит при возвратном глаголе «klæde sig på», sin — притяжательное, относящееся к подлежащему Peter. Две однородные части можно поменять местами.'},
 {id:'g12-09',cat:'relative',type:'transform',prompt:'Jeg har en nabo. Han spiller trommer hver aften.',instruction:'Объедини в одно предложение с относительным придаточным (der или som).',answers:['Jeg har en nabo, der spiller trommer hver aften.','Jeg har en nabo, som spiller trommer hver aften.'],why:'Относительное слово заменяет подлежащее «han», поэтому подходят и der, и som. Перед придаточным ставится запятая.'},
 {id:'g12-10',cat:'compare',type:'gap',stem:'Af alle mine kolleger er hun den, der arbejder ___.',options:['mere','mest','flere','flest'],answer:1,why:'После «af alle» нужна превосходная степень наречия: «arbejder mest». Mere — сравнительная степень, flere и flest употребляются с исчисляемыми существительными.'}
]}

];
